<?php require_once __DIR__.'/config.php';require_login();header('Content-Type: application/json; charset=utf-8');$level=$_GET['level']??'';$province=trim((string)($_GET['province']??''));$municipality=trim((string)($_GET['municipality']??''));if($level==='provinces'){$q=$pdo->query("SELECT DISTINCT province FROM aics_address_cache WHERE province<>'' ORDER BY province");echo json_encode(array_column($q->fetchAll(),'province'),JSON_UNESCAPED_UNICODE);exit;}if($level==='municipalities'&&$province!==''){$st=$pdo->prepare("SELECT DISTINCT municipality FROM aics_address_cache WHERE UPPER(province)=UPPER(?) AND municipality<>'' ORDER BY municipality");$st->execute([$province]);echo json_encode(array_column($st->fetchAll(),'municipality'),JSON_UNESCAPED_UNICODE);exit;}if($level==='barangays'&&$province!==''&&$municipality!==''){$st=$pdo->prepare("SELECT DISTINCT barangay FROM aics_address_cache WHERE UPPER(province)=UPPER(?) AND UPPER(municipality)=UPPER(?) AND barangay<>'' ORDER BY barangay");$st->execute([$province,$municipality]);echo json_encode(array_column($st->fetchAll(),'barangay'),JSON_UNESCAPED_UNICODE);exit;}echo json_encode([]);